import{_ as t,o,c as s,a5 as n}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/report3_spec.md","filePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/report3_spec.md"}'),r={name:"feature/authentication/3-2-3-sign-in-with-google-oauth/report3_spec.md"};function i(a,e,l,c,g,u){return o(),s("div",null,[...e[0]||(e[0]=[n("<p><strong>3.2.3 Sign In with Google OAuth</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a Guest activates &quot;Sign in with Google&quot; on the sign-in or registration screen, sending the browser to GET /api/v1/auth/oauth/google.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST. The same handshake also serves a signed-in user linking Google to an existing account, outside this feature.</li><li><strong>Purpose</strong>: Let a user sign in with Google, create a local account on first use, and honour two-factor authentication when enabled.</li><li><strong>Interface</strong>: &quot;Sign in with Google&quot; button on the sign-in and registration screens. A redirect handshake: the browser leaves for Google&#39;s consent screen and returns to the application&#39;s callback route.</li><li><strong>Data Processing</strong>: Issues and stores a single-use state value, redirects to Google; on callback, validates the state, exchanges the code for a Google access token, fetches the Google profile, links or creates the local account, checks account status, then issues tokens or a two-factor challenge.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Google sign-in entry and return:</p><ul><li>Entry: &quot;Sign in with Google&quot; button on /login and /register.</li><li>Return: browser lands on /oauth-callback; reads token from the URL fragment, stores it, loads the profile, navigates to Dashboard; toast <strong>MSG11</strong> on success.</li><li>If callback carries error=ACCOUNT_SUSPENDED: dedicated toast (account suspended), navigates to /login.</li><li>If callback carries any other error, or no token: clears partial auth state, shows a generic OAuth-failure toast <strong>MSG12</strong>, navigates to /login.</li><li>When 2FA is enabled: browser lands on the two-factor code screen instead, carrying twoFactorToken as a query parameter.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: none entered by the user; Google supplies code and state (or error) on callback.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: providerId, email, emailVerifiedAt, passwordHash (absent for OAuth-only users), twoFactorEnabled, status, lastLoginAt, workspaceId, accessToken, refreshToken, twoFactorToken.</li><li><strong>Output</strong>: on success, a redirect carrying the access token in the URL fragment plus a refresh token cookie. When 2FA enabled, a redirect to the two-factor screen with a challenge token and no cookie. On a suspended/inactive account, a redirect with error=ACCOUNT_SUSPENDED. On any other failure, a redirect with error=oauth_failed.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-09</strong>: The state value is single-use, stored for 10 minutes, deleted on first read (CSRF protection). Missing/expired/unknown state -&gt; 400 OAUTH_STATE_INVALID, generic error toast <strong>MSG12</strong>.</li><li><strong>BR-10</strong>: Email is the linking anchor for OAuth; an existing account with the same email is reused and linked, no duplicate account created. Failed token exchange, or a Google profile without id/email or unverified email -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>.</li><li><strong>BR-11</strong>: One (provider, providerId) pair maps to exactly one user. First use creates a local account with email already verified and no password.</li><li><strong>BR-06</strong>: Suspended or inactive account -&gt; 403 ACCOUNT_SUSPENDED. Redirected distinctly to a dedicated error, separate from the generic OAuth-failure toast.</li><li><strong>BR-08</strong>: When 2FA is enabled, no access/refresh token issued; a two-factor challenge token is returned instead, same as email sign-in.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User cancels consent or Google returns an error -&gt; no authorization code present -&gt; generic error toast <strong>MSG12</strong>, no further call to Google.</li><li>Google profile has no id/email, or email not verified -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>.</li><li>A network error calling Google -&gt; treated as a generic login failure, toast <strong>MSG12</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The Guest activates &quot;Sign in with Google&quot; on /login or /register.</li><li>The system generates a single-use state value, stores it for 10 minutes, and redirects the browser to Google&#39;s consent screen.</li><li>The user authenticates with Google and grants consent.</li><li>Google redirects the browser back to the application&#39;s callback route with code and state.</li><li>The system validates the authorization code is present, consumes the state, exchanges the code for a Google access token, and fetches the Google profile.</li><li>The system links the Google identity to an existing account with the same email, or creates a new verified account with no password.</li><li>The system checks the account status and, with 2FA disabled, records the sign-in, resolves the active workspace, and issues an access token and a refresh token.</li><li>The system sets the refresh token cookie and redirects to the callback page carrying the access token.</li><li>The screen reads the token, loads the profile, stores it, shows toast <strong>MSG11</strong>, and navigates to the Dashboard.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: The user cancels consent or Google returns an error -&gt; generic error toast <strong>MSG12</strong>, no further call to Google. 4.a2: The Guest retries &quot;Sign in with Google&quot;.</li><li>5.a1: The state is missing, already used/expired, or belongs to another provider (BR-09) -&gt; 400 OAUTH_STATE_INVALID, toast <strong>MSG12</strong>. 5.a2: The Guest retries.</li><li>5.b1: Token exchange fails, or the Google profile has no email or an unverified email (BR-10) -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>. 5.b2: The Guest retries, or signs in with email/password instead.</li><li>5.c1: A network error occurs while calling Google -&gt; generic failure redirect, toast <strong>MSG12</strong>. 5.c2: The Guest retries.</li><li>7.a1: The account is suspended or deactivated (BR-06) -&gt; 403 ACCOUNT_SUSPENDED, dedicated suspended-account toast. 7.a2: The Guest contacts support.</li><li>7.b1: 2FA is enabled on the account (BR-08) -&gt; no access/refresh token issued; a challenge token is returned instead. 7.b2: The browser is sent to the two-factor code screen to complete sign-in.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Google identity is linked to a local account, created on first use with email already verified and no password.</li><li>The sign-in is recorded, unless the user still has to complete two-factor verification.</li><li>An access token and a refresh-token cookie are issued, or a two-factor challenge token when 2FA is enabled.</li></ul>",14)])])}const p=t(r,[["render",i]]);export{h as __pageData,p as default};
